import{_ as p,a0 as l,w as n,s as u,ao as a,I as e,x as o,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Linux 用户的 7 个 Sudo 技巧和改进 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 用户的 7 个 Sudo 技巧和改进 | LCTT (202312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 用户的 7 个 Sudo 技巧和改进 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 用户的 7 个 Sudo 技巧和改进 | LCTT (202312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202312/20231205 7 Sudo Tips and Tweaks for Linux Users","title":"Linux 用户的 7 个 Sudo 技巧和改进","tag":"202312","desc":""},"relativePath":"202312/20231205 7 Sudo Tips and Tweaks for Linux Users.md","filePath":"[post].md"}'),r={name:"202312/20231205 7 Sudo Tips and Tweaks for Linux Users.md"};function g(c,s,h,k,b,f){const d=l("Link");return n(),u("div",null,[s[44]||(s[44]=a('<h1 id="linux-用户的-7-个-sudo-技巧和改进" tabindex="-1">Linux 用户的 7 个 Sudo 技巧和改进 <a class="header-anchor" href="#linux-用户的-7-个-sudo-技巧和改进" aria-label="Permalink to “Linux 用户的 7 个 Sudo 技巧和改进”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202312/14/232352wzxtu2pp6dxg4ou4.jpg" alt=""></p><blockquote><p>用这些技巧释放 sudo 的力量 💪</p></blockquote><p>你应该熟悉 sudo 吧？肯定有过使用的经验。</p><p>对多数 Linux 用户来说，<code>sudo</code> 就像一个神器，赋予了他们作为 root 用户执行任意命令或切换到 root 用户身份的能力。</p><p>其实这只掌握了一半的真相。<code>sudo</code> 绝非仅仅只是一条命令，<strong><code>sudo</code> 是一款你可以根据需求和偏好去定制的工具</strong>。</p><p>Ubuntu、Debian 以及其他的发行版在默认的配置下，赋予了 <code>sudo</code> 以 root 用户的身份执行任意命令的权限。这让很多用户误以为 <code>sudo</code> 就像一个魔法开关，瞬间可以获取到 root 权限。</p><p><strong>比如说，系统管理员可以设置成只有属于特定的 <code>dev</code> 组的部分用户才能用 <code>sudo</code> 来执行 <code>nginx</code> 命令。这些用户将无法用 <code>sudo</code> 执行任何其他命令或切换到 root 用户。</strong></p><p>如果你对此感到惊讶，那很可能是你一直在使用 <code>sudo</code>，但对其底层的工作原理并没有太多了解。</p><p>在这个教程中，我并不会解释 <code>sudo</code> 是如何运作的，这个主题我会在另一天讲解。</p><p>在这篇文章中，你将看到 <code>sudo</code> 的不同特性可以如何被调试和改进。有些可能真的很有用，有些可能完全没什么帮助，但是挺有趣。</p>',11)),e("blockquote",null,[e("p",null,[s[1]||(s[1]=o("🚧 请不要随意去尝试所有提到的改进。如果处理不慎，你可能会遭遇无法运行 ",-1)),s[2]||(s[2]=e("code",null,"sudo",-1)),s[3]||(s[3]=o(" 的混乱状态。在大多数情况下，平静阅读并知道这些就好。如果你决定尝试一些改进步骤，",-1)),i(d,{href:"https://itsfoss.com/backup-restore-linux-timeshift/"},{default:t(()=>[...s[0]||(s[0]=[o("请先备份你的系统设置",-1)])]),_:1}),s[4]||(s[4]=o("，这样在需要的时候能把事情恢复到正常。",-1))])]),s[45]||(s[45]=e("h3",{id:"_1、编辑-sudo-配置时-请始终使用-visudo",tabindex:"-1"},[o("1、编辑 sudo 配置时，请始终使用 visudo "),e("a",{class:"header-anchor",href:"#_1、编辑-sudo-配置时-请始终使用-visudo","aria-label":"Permalink to “1、编辑 sudo 配置时，请始终使用 visudo”"},"​")],-1)),s[46]||(s[46]=e("p",null,[e("code",null,"sudo"),o(" 命令是通过 "),e("code",null,"/etc/sudoers"),o(" 文件进行配置的。")],-1)),e("p",null,[s[6]||(s[6]=o("虽然你可以用你最喜欢的 ",-1)),i(d,{href:"https://itsfoss.com/command-line-text-editors-linux/"},{default:t(()=>[...s[5]||(s[5]=[o("终端文本编辑器",-1)])]),_:1}),s[7]||(s[7]=o(" 编辑这个文件，比如 Micro、NeoVim 等，但你",-1)),s[8]||(s[8]=e("strong",null,"千万不要",-1)),s[9]||(s[9]=o("这么做。",-1))]),s[47]||(s[47]=a('<p>为什么这么说呢？因为该文件中的任何语法错误都会让你的系统出问题，导致 <code>sudo</code> 无法工作。这可能会使得你的 Linux 系统无法正常使用。</p><p>你只需要这样使用即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo visudo</span></span></code></pre></div><p>传统上，<code>visudo</code> 命令会在 Vi 编辑器中打开 <code>/etc/sudoers</code> 文件。如果你用的是 Ubuntu，那么会在 Nano 中打开。</p><p><img src="https://itsfoss.com/content/images/2023/02/save-file-in-nano-editor.png" alt=""></p><p>这么做的好处在于，<strong>visudo 会在你试图保存更改时执行语法检查</strong>。这能确保你不会因为语法错误而误改 <code>sudo</code> 配置。</p><p><img src="https://itsfoss.com/content/images/2023/12/visudo-syntax-validation.png" alt="visudo 在保存到 sudoers 文件的变更前检查语法"></p><p>好了！现在你可以看看 <code>sudo</code> 配置的一些改变。</p><blockquote><p>💡 我建议你备份 <code>/etc/sudoers</code> 文件（<code>sudo cp /etc/sudoers /etc/sudoers.bak</code>）。这样，如果你不确定你做了哪些更改，或者你想恢复到默认的 sudo 配置，那你可以从备份文件中复制。</p></blockquote><h3 id="_2、输入-sudo-密码时显示星号" tabindex="-1">2、输入 sudo 密码时显示星号 <a class="header-anchor" href="#_2、输入-sudo-密码时显示星号" aria-label="Permalink to “2、输入 sudo 密码时显示星号”">​</a></h3><p>我们的这种输入行为是从 UNIX 系统中继承下来的。当你在终端输入 <code>sudo</code> 密码时，屏幕上不会有任何显示。这种缺乏反馈的现象，往往让新的 Linux 用户怀疑自己的系统已经卡住了。</p><p>人们常说，这是一项安全功能。或许在上个世纪是这样，但我个人觉得我们没有必要继续这样下去。</p><p>不过，一些发行版，如 Linux Mint，已经对 <code>sudo</code> 进行了优化，当你输入密码时会显示星号。</p><p>这样的方式更符合我们的日常经验。</p><p>如果想让 <code>sudo</code> 输入密码时显示星号，运行 <code>sudo visudo</code> 并找到以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Defaults env_reset</span></span></code></pre></div><p>然后将其更改为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Defaults env_reset,pwfeedback</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/12/sudo-password-feedback.png" alt=""></p><blockquote><p>💡 在某些发行版中，比如 Arch，你可能找不到 <code>Defaults env_reset</code> 这一行。如果这样的话，只需新增一行 <code>Defaults env_reset, pwfeedback</code> 就可以了。</p></blockquote><p>现在，当 <code>sudo</code> 需要你输入密码时，你会看到输入的密码变成了星号。</p><p><img src="https://itsfoss.com/content/images/2023/12/sudo-password-with-asterisk-display.png" alt=""></p><blockquote><p>✋ 如果你注意到即使密码正确也无法通过一些图形化应用，如软件中心，那就该撤销这项更改。一些较旧的论坛帖子曾提到过此类问题，虽然我自己还未遇到过。</p></blockquote><h3 id="_3、增加-sudo-密码超时时限" tabindex="-1">3、增加 sudo 密码超时时限 <a class="header-anchor" href="#_3、增加-sudo-密码超时时限" aria-label="Permalink to “3、增加 sudo 密码超时时限”">​</a></h3><p>当你首次使用 <code>sudo</code> 时，它会要求输入密码。但在随后相当一段时间里，你使用 <code>sudo</code> 执行命令就无需再次输入密码。</p><p>我们将这个时间间隔称为 <code>sudo</code> 密码超时 （暂且称为 SPT，这是我刚刚编的说法，请不要真的这样称呼 😁）。</p><p>不同的发行版有不同的超时时间。可能是 5 分钟，也可能是 15 分钟。</p><p>你可以根据自己的喜好来改变这个设置，设定一个新的 <code>sudo</code> 密码超时时限。</p><p>像你之前看到的，编辑 <code>sudoers</code> 文件，找到含有 <code>Defaults env_reset</code> 的行，并在此行添加 <code>timestamp_timeout=XX</code>，使其变成如下形式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Defaults        env_reset, timestamp_timeout=XX</span></span></code></pre></div><p>其中 <code>XX</code> 是以分钟为单位的超时时长。</p><p>如果你还有其他参数，例如你在上一节中看到的星号反馈，它们都可以在一行中组合起来：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Defaults        env_reset, timestamp_timeout=XX, pwfeedback</span></span></code></pre></div><blockquote><p>💡 同样地，你还可以控制密码重试的次数上限。使用 <code>passwd_tries=N</code> 来修改用户可以输入错误密码的次数。</p></blockquote><h3 id="_4、在不输入密码的情况下使用-sudo" tabindex="-1">4、在不输入密码的情况下使用 sudo <a class="header-anchor" href="#_4、在不输入密码的情况下使用-sudo" aria-label="Permalink to “4、在不输入密码的情况下使用 sudo”">​</a></h3><p>行！你已经增加了 <code>sudo</code> 密码超时时限（或者称之为 SPT。哇塞！你还在坚持这个叫法 😛）。</p><p>这样很好。我的意思是，毕竟没人愿意每几分钟就输入一次密码。</p><p>扩大超时时限是一方面，另一方面则是尽可能不去使用它。</p><p>是的，你没听错。你就是可以在无需输入密码的情况下使用 <code>sudo</code>。</p><p>从安全角度来看，这听起来似乎很冒险，对吧？的确如此，但在某些实际情况下，你确实会更青睐无密码的 <code>sudo</code>。</p><p>例如，如果你需要远程管理多台 Linux 服务器，并为了避免总是使用 root，你在这些服务器上创建了一些 <code>sudo</code> 用户。辛酸的是，你会有太多的密码。而你又不想对所有的服务器使用同一的 <code>sudo</code> 密码。</p><p>在这种情况下，你可以仅设置基于密钥的 SSH 访问方式，并允许使用无需密码的 <code>sudo</code>。这样，只有获得授权的用户才能访问远程服务器，也不用再记住 <code>sudo</code> 密码。</p>',42)),e("p",null,[s[11]||(s[11]=o("我在 ",-1)),i(d,{href:"https://digitalocean.pxf.io/JzK74r"},{default:t(()=>[...s[10]||(s[10]=[o("DigitalOcean",-1)])]),_:1}),s[12]||(s[12]=o(" 上部署的测试服务器上就采用了这种方法，用来测试开源工具和服务。",-1))]),s[48]||(s[48]=a('<p>好处是这可以按用户进行设置。使用以下命令打开 <code>/etc/sudoers</code> 文件进行编辑：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo visudo</span></span></code></pre></div><p>然后添加如下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>user_name ALL=(ALL) NOPASSWD:ALL</span></span></code></pre></div><p>当然，你需要将上面行中的 <code>user_name</code> 替换为实际的用户名。</p><p>保存文件后，你就可以享受无密码的 <code>sudo</code> 生活了。</p><h3 id="_5、配置独立的-sudo-日志文件" tabindex="-1">5、配置独立的 sudo 日志文件 <a class="header-anchor" href="#_5、配置独立的-sudo-日志文件" aria-label="Permalink to “5、配置独立的 sudo 日志文件”">​</a></h3><p>查阅 syslog 或 journal 日志，我们可以找到关于 <code>sudo</code> 的所有条目，但若需要单独针对 <code>sudo</code> 的记录，可以专门创建一个自定义的日志文件。例如，选择 <code>/var/sudo.log</code> 文件来存储日志。这个新的日志文件无需手动创建，如果不存在，系统会自动生成。</p><p>编辑 <code>/etc/sudoers</code> 文件，采用 <code>visudo</code> 命令，并在其中添加以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Defaults  logfile=&quot;/var/log/sudo.log&quot;</span></span></code></pre></div><p>保存该文件后，便可以在其中查看哪些命令在何时、由哪位用户通过 <code>sudo</code> 运行了。</p><p><img src="https://itsfoss.com/content/images/2023/12/sudo-log-file.png" alt=""></p><h3 id="_6、限制特定用户组使用-sudo-执行特定命令" tabindex="-1">6、限制特定用户组使用 sudo 执行特定命令 <a class="header-anchor" href="#_6、限制特定用户组使用-sudo-执行特定命令" aria-label="Permalink to “6、限制特定用户组使用 sudo 执行特定命令”">​</a></h3><p>这是一种高级解决方案，系统管理员在需要跨部门共享服务器的多用户环境中会使用。</p>',14)),e("p",null,[s[14]||(s[14]=o("开发者可能会需要以 root 权限运行 Web 服务器或其他程序，但全权给予他们 ",-1)),s[15]||(s[15]=e("code",null,"sudo",-1)),s[16]||(s[16]=o(" 权限会带来安全风险。我建议在群组级别进行此项操作。例如，创建命名为 ",-1)),s[17]||(s[17]=e("code",null,"coders",-1)),s[18]||(s[18]=o(" 的群组，并允许它们运行在 ",-1)),s[19]||(s[19]=e("code",null,"/var/www",-1)),s[20]||(s[20]=o(" 和 ",-1)),s[21]||(s[21]=e("code",null,"/opt/bin/coders",-1)),s[22]||(s[22]=o(" 目录下的命令（或可执行文件），以及 ",-1)),i(d,{href:"https://itsfoss.com/inxi-system-info-linux/"},{default:t(()=>[...s[13]||(s[13]=[o("inxi 命令",-1)])]),_:1}),s[23]||(s[23]=o("（路径是 ",-1)),s[24]||(s[24]=e("code",null,"/usr/bin/inxi",-1)),s[25]||(s[25]=o(" 的二进制文件）。这是一个假想情景，实际操作请谨慎对待。",-1))]),s[49]||(s[49]=a('<p>接下来，用 <code>sudo visudo</code> 编辑 sudoer 文件，再添加以下行:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>%coders   ALL=(ALL:ALL) /var/www,/opt/bin/coders,/usr/bin/inxi</span></span></code></pre></div><p>如有需要，可以添加 <code>NOPASSWD</code> 参数，这样允许使用 <code>sudo</code> 运行的命令就不再需要密码了。</p><p>关于 <code>ALL=(ALL:ALL)</code> 的详细解读，我们将会在其他文章中进行讲解，毕竟这篇文章已经解释的内容足够多了。</p><h3 id="_7、检查用户的-sudo-权限" tabindex="-1">7、检查用户的 sudo 权限 <a class="header-anchor" href="#_7、检查用户的-sudo-权限" aria-label="Permalink to “7、检查用户的 sudo 权限”">​</a></h3><p>好吧，这是个小提示，而不是系统调优技巧。</p><p>如何确认一个用户是否具有 <code>sudo</code> 权限呢？可能有人会说，查看他们是否是 <code>sudo</code> 组的成员。但这并不一定准确，因为有些发行版用的是 <code>wheel</code> 代替 <code>sudo</code> 分组。</p><p>更佳的方法是利用 <code>sudo</code> 内建的功能，看看用户具有哪种 <code>sudo</code> 权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo -l -U user_name</span></span></code></pre></div><p>这将显示出用户具有执行部分命令或所有命令的 <code>sudo</code> 权限。</p><p><img src="https://itsfoss.com/content/images/2023/12/check-sudo-access.png" alt=""></p><p>如你所见，我拥有自定义日志文件、密码反馈以及执行所有命令的 <code>sudo</code> 权限。</p><p>如果一个用户完全没有 <code>sudo</code> 权限，你将看到如下提示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>User prakash is not allowed to run sudo on this-that-server.</span></span></code></pre></div><h3 id="🎁-附加内容-输错-sudo-密码时-让系统-侮辱-你" tabindex="-1">🎁 附加内容：输错 sudo 密码时，让系统“侮辱”你 <a class="header-anchor" href="#🎁-附加内容-输错-sudo-密码时-让系统-侮辱-你" aria-label="Permalink to “🎁 附加内容：输错 sudo 密码时，让系统“侮辱”你”">​</a></h3><p>这是个我在文章开头提到的“无用”小调整。</p><p>我想你在使用 <code>sudo</code> 时肯定曾误输过密码，对吧？</p>',17)),e("p",null,[s[27]||(s[27]=o("这个小技巧就是，在你每次输错密码时，",-1)),i(d,{href:"https://itsfoss.com/sudo-insult-linux/"},{default:t(()=>[...s[26]||(s[26]=[o("让 sudo 抛出随机的“侮辱”",-1)])]),_:1}),s[28]||(s[28]=o("。",-1))]),s[50]||(s[50]=a('<p>用 <code>sudo visudo</code> 修改 <code>sudo</code> 配置文件，然后添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Defaults   insults</span></span></code></pre></div><p>修改后，你可以故意输错密码，测试新的设置。</p><p><img src="https://itsfoss.com/content/images/2023/12/sudo-insults.png" alt=""></p><p>你可能在想，谁会喜欢被侮辱呢？<strong>只有粉丝</strong>可以以直白的方式告诉你 😇</p><h3 id="你是如何运用-sudo-的" tabindex="-1">你是如何运用 sudo 的？ <a class="header-anchor" href="#你是如何运用-sudo-的" aria-label="Permalink to “你是如何运用 sudo 的？”">​</a></h3><p><img src="https://itsfoss.com/content/images/2023/12/sudo-meme.png" alt=""></p><p>我知道定制化的可能性无穷无尽，但其实，一般的 Linux 用户并不会去自定义 <code>sudo</code>。</p><p>尽管如此，我还是热衷于与你分享这些因为你可能会发现一些新奇且实用的东西。</p><p>💬 那么，你有发现什么新的东西吗？请在评论区告诉我。你有一些秘密的 <code>sudo</code> 技巧欢迎和大家分享！</p><p><em>（题图：DA/a12900e5-e197-455e-adfc-0b52e4305b91）</em></p><hr>',12)),e("p",null,[s[30]||(s[30]=o("via: ",-1)),i(d,{href:"https://itsfoss.com/sudo-tips/"},{default:t(()=>[...s[29]||(s[29]=[o("https://itsfoss.com/sudo-tips/",-1)])]),_:1})]),e("p",null,[s[35]||(s[35]=o("作者：",-1)),i(d,{href:"https://itsfoss.com/author/abhishek/"},{default:t(()=>[...s[31]||(s[31]=[o("Abhishek Prakash",-1)])]),_:1}),s[36]||(s[36]=o(" 选题：",-1)),i(d,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[32]||(s[32]=[o("lujun9972",-1)])]),_:1}),s[37]||(s[37]=o(" 译者：",-1)),i(d,{href:"https://linux.cn/lctt/ChatGPT"},{default:t(()=>[...s[33]||(s[33]=[o("ChatGPT",-1)])]),_:1}),s[38]||(s[38]=o(" 校对：",-1)),i(d,{href:"https://github.com/wxy"},{default:t(()=>[...s[34]||(s[34]=[o("wxy",-1)])]),_:1})]),e("p",null,[s[41]||(s[41]=o("本文由 ",-1)),i(d,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[39]||(s[39]=[o("LCTT",-1)])]),_:1}),s[42]||(s[42]=o(" 原创编译，",-1)),i(d,{href:"https://linux.cn/"},{default:t(()=>[...s[40]||(s[40]=[o("Linux中国",-1)])]),_:1}),s[43]||(s[43]=o(" 荣誉推出",-1))])])}const v=p(r,[["render",g]]);export{T as __pageData,v as default};
